$root = '/home/u730243224/domains/bta33kar.com/public_html/';
$f1 = $root . 'platform/plugins/real-estate/src/Providers/HookServiceProvider.php';
$f2 = $root . 'platform/themes/flex-home/views/real-estate/property-category.blade.php';

$base_h1 = 'c6f119c4653e8f0b89c27f9b87687ee47de606c584b2254eb1733257a377aad6';
$base_h2 = '5e6c5bb3c573de47b3e071ffab43b62a0d025fb81b5f7c336749147ce9626851';

$curr_h1 = hash_file('sha256', $f1);
$curr_h2 = hash_file('sha256', $f2);

if ($curr_h1 !== $base_h1 || $curr_h2 !== $base_h2) {
    echo json_encode(['status' => 'ERROR', 'msg' => 'Baseline mismatch', 'f1' => $curr_h1, 'f2' => $curr_h2]);
    return;
}

$c1 = base64_decode('');
$c2 = base64_decode('');

$exp_h1 = '6d1a8959d37824cd98a2474fb44a58acd482cf41cd738350d7bcaeb9c924c02e';
$exp_h2 = '51824b424aec1c26a776abcb4956448b4d0ea3c7d1565586d067fb9334a44822';

if (hash('sha256', $c1) !== $exp_h1 || hash('sha256', $c2) !== $exp_h2) {
    echo json_encode(['status' => 'ERROR', 'msg' => 'Payload hash mismatch']);
    return;
}

file_put_contents($f1, $c1);
file_put_contents($f2, $c2);

if (function_exists('opcache_invalidate')) {
    @opcache_invalidate($f1, true);
}

// Also clear compiled views in storage/framework/views so blade changes take effect
$viewsDir = $root . 'storage/framework/views/';
if (is_dir($viewsDir)) {
    foreach (glob($viewsDir . '*.php') as $vFile) {
        @unlink($vFile);
    }
}

$new_h1 = hash_file('sha256', $f1);
$new_h2 = hash_file('sha256', $f2);

$success = ($new_h1 === $exp_h1 && $new_h2 === $exp_h2);
echo json_encode([
    'status' => $success ? 'SUCCESS' : 'FAILURE',
    'f1' => ['sha256' => $new_h1, 'match' => ($new_h1 === $exp_h1)],
    'f2' => ['sha256' => $new_h2, 'match' => ($new_h2 === $exp_h2)],
    'time' => date('c')
]);
